package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimDue;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimShare;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.claim.LateCharge;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.pool.PoolRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;

/**
 * The sheet's figures as the screen shows them: each person's claimed (the amounts of their claims that count added up, leaving out corrections; a person's OPEN or PENDING claims, once their retirement date is reached, not bound by a statement, do not, nor do deferred claims; a held claim still does) and
 * due-total (the figures of the claims that count live — held ones included, each with its late charge, added up, less
 * the parts of them other people hold by a share, plus their own parts of others' shared claims (see ClaimShare#part, at their own grade's rate); n/a when their grade has no rate today and no counting claim
 * has a figure, kept or at the grade in force on its date; at most the sheet's cap less their cut total, not below 0.00), overdue-total (the figures, late charge included, of those claims that are overdue — open, their due-by plus
 * their grace (see LateCharge#lateFrom) before today — added up, skipping n/a; not capped), and the sheet's claimed-total, due-total and overdue-total (everyone's added up, skipping n/a; the due-total and
 * overdue-total leave out the single highest and the single lowest figure when three or more people have one).
 *
 * A change takes the figures before it ({@link #take}) and, after its own audit lines, writes ROLLUP for every
 * person whose figures (claimed, due-total or overdue-total) moved (a person new to the sheet counts as moved), then
 * TOTALS when any of the sheet's three totals moved ({@link #record}), then ALERT, in list order, for every person
 * whose due-total went from at or below the sheet's alert threshold (or no due-total: n/a, or new to the sheet) to
 * above it (none while the threshold is off).
 */
@Service
public class Rollup {

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetRepository sheets;
    private final SettingRepository settings;
    private final PoolRepository pools;
    private final Audit audit;

    public Rollup(PersonRepository people, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
            SettingRepository settings, PoolRepository pools, Audit audit) {
        this.pools = pools;
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.settings = settings;
        this.audit = audit;
    }

    /** Every person's figures on the sheet now, in list order (see PersonRepository#list). */
    public RollupBefore take(String sheetId) {
        LocalDate today = sheets.today(sheetId);
        BigDecimal cap = settings.cap(sheetId);
        LateCharge late = LateCharge.of(sheetId, sheets, settings, claims);
        List<Claim> all = claims.list(sheetId);
        List<Person> listed = people.list(sheetId);
        Map<Long, BigDecimal> parts = shareParts(sheetId, today, late, all, listed);
        Map<Long, BigDecimal> cuts = cap == null ? Map.of() : pools.cutTotals(sheetId, null);
        Map<Long, Figures> figures = new LinkedHashMap<>();
        for (Person person : listed) {
            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
            BigDecimal due = BigDecimal.ZERO.setScale(2);
            BigDecimal overdue = BigDecimal.ZERO.setScale(2);
            BigDecimal settled = BigDecimal.ZERO.setScale(2);
            int overdueCount = 0;
            boolean figured = false;
            for (Claim c : all) {
                if (c.personId() != person.id()) {
                    continue;
                }
                if (c.corrects() == null && ClaimDue.countsClaimed(c, person, today)) {
                    claimed = claimed.add(c.amount());
                }
                if (!ClaimDue.countsLive(c, person, today)) {
                    continue;
                }
                BigDecimal figure = late.add(c, ClaimDue.figure(c, person.gradeOn(c.date()), rates, late.rounding()), settings.floor(sheetId, c.date()));
                figured |= figure != null;
                boolean overdueNow = ClaimDue.isOpen(c) && late.lateFrom(c).isBefore(today);
                if (overdueNow) {
                    overdueCount++;
                }
                if (figure != null && c.status() == ClaimStatus.SETTLED && c.corrects() == null) {
                    settled = settled.add(figure);
                }
                if (figure != null) {
                    due = due.add(figure);
                    if (overdueNow) {
                        overdue = overdue.add(figure);
                    }
                }
            }
            BigDecimal part = parts.get(person.id());
            if (part != null) {
                due = due.add(part);
                figured = true;
            }
            String dueTotal = rates.find(sheetId, person.gradeOn(today), today) == null && !figured ? "n/a"
                    : SettingRepository.capped(due, cap, cuts.get(person.id())).toPlainString();
            figures.put(person.id(), new Figures(person.name(), claimed.toPlainString(), dueTotal,
                    overdue.toPlainString(), score(settled, overdueCount)));
        }
        return new RollupBefore(figures);
    }

    /** What the shares of the sheet's claims that count live move in each person's due-total now (see #shareParts), by
     *  person id. */
    public Map<Long, BigDecimal> shareParts(String sheetId) {
        return shareParts(sheetId, sheets.today(sheetId), LateCharge.of(sheetId, sheets, settings, claims),
                claims.list(sheetId), people.list(sheetId));
    }

    /** What the shares of the claims that count live move in each person's due-total, by person id: each holder gains
     *  their part of the claim (see ClaimShare#part: at their own grade's rate; frozen with the due once settled), and
     *  the claim's own person loses it. A person with no
     *  share of a claim that has a figure is left out. */
    private Map<Long, BigDecimal> shareParts(String sheetId, LocalDate today, LateCharge late, List<Claim> all,
            List<Person> listed) {
        Map<Long, List<ClaimShare>> shares = claims.shares(sheetId, (LocalDate) null);
        Map<Long, BigDecimal> parts = new HashMap<>();
        if (shares.isEmpty()) {
            return parts;
        }
        Map<Long, Person> byId = new HashMap<>();
        listed.forEach((p) -> byId.put(p.id(), p));
        for (Claim c : all) {
            List<ClaimShare> held = shares.get(c.id());
            Person owner = byId.get(c.personId());

